UPDATE first_visit_appointment
appointment_no = #{appointmentNo}, student_id = #{studentId}, form_id = #{formId}, interviewer_id = #{interviewerId}, duty_schedule_id = #{dutyScheduleId}, appointment_date = #{appointmentDate}, slot_id = #{slotId}, room_id = #{roomId}, appointment_status = #{appointmentStatus}, priority_flag = #{priorityFlag}, audit_admin_id = #{auditAdminId}, audit_time = #{auditTime}, audit_remark = #{auditRemark}, cancel_reason = #{cancelReason}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT fva.id, fva.appointment_no, fva.student_id, su.real_name AS student_name, sp.student_no, sp.college, fva.form_id, fvf.main_problem, fvf.problem_description, fvf.risk_score, fvf.risk_level, fva.appointment_date, fva.slot_id, ts.slot_name, ts.start_time, ts.end_time, fva.room_id, cr.room_name, fva.interviewer_id, interviewer_su.real_name AS interviewer_name, fva.duty_schedule_id, fva.appointment_status, fva.priority_flag, fva.audit_admin_id, admin_su.real_name AS audit_admin_name, fva.audit_time, fva.audit_remark, fva.cancel_reason, fva.create_time, fva.update_time FROM first_visit_appointment fva LEFT JOIN sys_user su ON fva.student_id = su.id LEFT JOIN student_profile sp ON su.id = sp.user_id LEFT JOIN first_visit_form fvf ON fva.form_id = fvf.id LEFT JOIN time_slot ts ON fva.slot_id = ts.id LEFT JOIN counseling_room cr ON fva.room_id = cr.id LEFT JOIN staff_profile isp ON fva.interviewer_id = isp.id LEFT JOIN sys_user interviewer_su ON isp.user_id = interviewer_su.id LEFT JOIN sys_user admin_su ON fva.audit_admin_id = admin_su.id WHERE 1=1
AND (su.real_name LIKE CONCAT('%', #{keyword}, '%') OR sp.student_no LIKE CONCAT('%', #{keyword}, '%') OR fva.appointment_no LIKE CONCAT('%', #{keyword}, '%'))
AND fva.appointment_status = #{status}
AND fvf.risk_level = #{riskLevel}
AND fva.appointment_date >= #{startDate}
AND fva.appointment_date <= #{endDate}
AND fva.priority_flag = #{priorityFlag}
ORDER BY CASE fvf.risk_level WHEN 'URGENT' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 END, fva.priority_flag DESC, fva.create_time DESC

SELECT COUNT(*)
FROM first_visit_appointment fva
LEFT JOIN sys_user su ON fva.student_id = su.id
LEFT JOIN student_profile sp ON su.id = sp.user_id
LEFT JOIN first_visit_form fvf ON fva.form_id = fvf.id
WHERE 1=1

    AND (su.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR fva.appointment_no LIKE CONCAT('%', #{keyword}, '%'))


    AND fva.appointment_status = #{status}


    AND fvf.risk_level = #{riskLevel}


    AND fva.appointment_date >= #{startDate}


    AND fva.appointment_date <= #{endDate}


    AND fva.priority_flag = #{priorityFlag}

SELECT COUNT(*) FROM first_visit_appointment
WHERE student_id = #{studentId}
  AND appointment_status IN ('PENDING', 'APPROVED')

      AND id != #{excludeId}
